const paths = process.argv.slice(2);
const dec = s => s.replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#x27;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/<[^>]+>/g,'').replace(/\s+/g,' ').trim();
for (const p of paths) {
  let html='';
  for (let i=0;i<3;i++){ try { const r = await fetch('http://localhost:3100'+p,{signal:AbortSignal.timeout(90000)}); html = await r.text(); break;} catch(e){ await new Promise(r=>setTimeout(r,20000)); } }
  const titles = [...html.matchAll(/<title>([\s\S]*?)<\/title>/g)].map(m=>dec(m[1]));
  const t = titles.filter(x=>x.includes('|')).pop() || titles.pop() || '';
  const d = dec((html.match(/<meta name="description" content="([^"]*)"/)||[])[1]||'');
  const h1 = dec((html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/)||[])[1]||'');
  const h2 = [...html.matchAll(/<h2[^>]*>([\s\S]*?)<\/h2>/g)].map(m=>dec(m[1])).slice(0,10);
  const main = html.split(/<h1/)[1]||'';
  const ps = [...main.matchAll(/<p[^>]*>([\s\S]*?)<\/p>/g)].map(m=>dec(m[1])).filter(x=>x.length>60).slice(0,1);
  console.log(`## ${p}\nT(${t.length}): ${t}\nD(${d.length}): ${d}\nH1: ${h1}\nH2: ${h2.join(' | ')}\nP1: ${ps[0]||''}\n`);
}

